import {
    BaseRowModel
} from "./base_row";
const SELECTORS = {
    expandCell: "dx-command-expand"
};
export class GroupRowModel extends BaseRowModel {
    getExpandCell() {
        const row = this.getElement();
        return row.querySelector(`.${SELECTORS.expandCell}`)
    }
    getCells() {
        const row = this.getElement();
        return row.querySelectorAll("td")
    }
}
